WITH monthly_totals AS (SELECT d.d_year, d.d_moy AS month, ib.ib_income_band_sk, SUM(cr.cr_return_amount) AS month_return_amount, SUM(cr.cr_net_loss) AS month_net_loss, CASE WHEN SUM(cr.cr_return_amount) > 10000 THEN 'HIGH' ELSE 'NORMAL' END AS return_amount_category FROM catalog_returns cr JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk JOIN household_demographics hd ON cr.cr_returning_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk WHERE d.d_year = 2020 GROUP BY d.d_year, d.d_moy, ib.ib_income_band_sk) SELECT mt.d_year, mt.month, mt.ib_income_band_sk, mt.month_return_amount, mt.month_net_loss, mt.return_amount_category, SUM(mt.month_return_amount) OVER (PARTITION BY mt.d_year ORDER BY mt.month ROWS UNBOUNDED PRECEDING) AS cumulative_return_amount, LAG(mt.month_return_amount) OVER (PARTITION BY mt.d_year ORDER BY mt.month) AS prev_month_return_amount, RANK() OVER (PARTITION BY mt.d_year ORDER BY mt.month_return_amount DESC) AS month_return_rank FROM monthly_totals mt ORDER BY mt.d_year, mt.month
